/**
 * GENERATED_VIDEO_FALLBACK — a short video generated by ElevenLabs for a sentence nothing else
 * could picture. VIDEO 649.
 *
 * ── Where it sits ───────────────────────────────────────────────────────────────────────────────
 *
 * Inside the existing generated-picture rung (see generatedImageFallback.ts), and nowhere else:
 *
 *   1  REAL / ARCHIVE / OPEN / STOCK   unchanged
 *   2  DATA / MAP GRAPHIC              unchanged
 *   3a AI GENERATED VIDEO              this module — logged GENERATED_VIDEO_FALLBACK
 *   3b AI GENERATED STILL              Stability, as before — when 3a has no key, is standing down,
 *                                      cannot cover the sentence, times out or is refused
 *   4  CHAPTER CARD                    unchanged
 *
 * The same decision (`generatedImageDecision`), the same prompt, the same tagging and the same
 * `adoptClip` route (TechnicalMediaGate → VisualJudge → ledger) as the still; only the file differs.
 * One generation per sentence, counted against the same per-film cap as the still.
 *
 * ── The API, as the official pages describe it ─────────────────────────────────────────────────
 *
 *   POST /v1/flows/video        header xi-api-key; body per model: model_id, prompt, duration_secs,
 *                               aspect_ratio (…); answer: id + status ("pending"). Asynchronous.
 *   GET  /v1/flows/video/{id}   status pending → generating → completed | failed; completed carries
 *                               content_url (a signed link, valid about an hour) + content_mime_type.
 *                               Poll no more than once every 10 s. Failed generations are not charged.
 *   402 paid_plan_required below the Pro plan; the key must carry the Image & Video permission.
 *
 * The model-specific body fields were read from the documentation's examples, not from a schema
 * this code can validate: `ELEVENLABS_VIDEO_EXTRA_JSON` lets an operator add or override fields
 * without a deploy, and a create request the service rejects costs nothing.
 *
 * ── What is never logged ────────────────────────────────────────────────────────────────────────
 *
 * The key, the request body and the signed content URL. The log carries the generation id, the
 * status, the HTTP status and timings.
 */
import { execFile } from "node:child_process";
import fs from "node:fs";
import { promisify } from "node:util";

import { classifyProviderFailure, formatProviderCooldown } from "./providerFailureClass";
import { resolveFFmpegBin } from "./ffmpegBinary";

const execFileAsync = promisify(execFile);

export const GENERATED_VIDEO_FALLBACK = "GENERATED_VIDEO_FALLBACK";

/** The provider name a generated video carries through the lineage, the archive and the timeline. */
export const GENERATED_VIDEO_PROVIDER = "elevenlabs_video";

const API_BASE = "https://api.elevenlabs.io";
export const DEFAULT_VIDEO_MODEL_ID = "veo-3.1-fast-generate-001";
export const DEFAULT_VIDEO_DURATION_SEC = 8;
/** The documentation's own floor for polling a video generation. */
export const VIDEO_POLL_MIN_MS = 10_000;
export const DEFAULT_VIDEO_MAX_WAIT_MS = 5 * 60_000;
/** Below this a "video" is not one: the download is refused before any probe. */
export const GENERATED_VIDEO_MIN_BYTES = 50_000;
const CREATE_TIMEOUT_MS = 30_000;
const POLL_TIMEOUT_MS = 20_000;
const DOWNLOAD_TIMEOUT_MS = 90_000;
const MAX_CONSECUTIVE_POLL_ERRORS = 3;

export type ElevenLabsVideoConfig = {
  key: string | null;
  /** Which variable the key came from: the video key, or the voice key as its fallback. */
  keySource: "video" | "voice" | null;
  modelId: string;
  durationSec: number;
  maxWaitMs: number;
  pollMs: number;
  extra: Record<string, unknown>;
};

export function elevenLabsVideoConfig(env: NodeJS.ProcessEnv = process.env): ElevenLabsVideoConfig {
  /**
   * ELEVENLABS_VIDEO_API_KEY when set; otherwise the voice key (ELEVENLABS_API_KEY), which works
   * when that key carries the Image & Video permission — one key, two uses. A key without it is
   * answered with 401/402/403 at create, stands the service down for 30 minutes and costs nothing.
   */
  const videoKey = env.ELEVENLABS_VIDEO_API_KEY?.trim() || null;
  const voiceKey = env.ELEVENLABS_API_KEY?.trim() || null;
  const key = videoKey ?? voiceKey;
  const dur = Number.parseFloat(env.ELEVENLABS_VIDEO_DURATION_SEC ?? "");
  const wait = Number.parseInt(env.ELEVENLABS_VIDEO_MAX_WAIT_MS ?? "", 10);
  const poll = Number.parseInt(env.ELEVENLABS_VIDEO_POLL_MS ?? "", 10);
  let extra: Record<string, unknown> = {};
  const raw = env.ELEVENLABS_VIDEO_EXTRA_JSON?.trim();
  if (raw) {
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) extra = parsed as Record<string, unknown>;
    } catch {
      /* an unreadable override is ignored, not obeyed */
    }
  }
  return {
    key,
    keySource: videoKey ? "video" : voiceKey ? "voice" : null,
    modelId: env.ELEVENLABS_VIDEO_MODEL_ID?.trim() || DEFAULT_VIDEO_MODEL_ID,
    durationSec: Number.isFinite(dur) && dur > 0 ? dur : DEFAULT_VIDEO_DURATION_SEC,
    maxWaitMs: Number.isFinite(wait) && wait >= VIDEO_POLL_MIN_MS ? wait : DEFAULT_VIDEO_MAX_WAIT_MS,
    pollMs: Number.isFinite(poll) ? Math.max(VIDEO_POLL_MIN_MS, poll) : VIDEO_POLL_MIN_MS,
    extra,
  };
}

/** True when the worker has a key for the video service; the rung is skipped silently without one. */
export function elevenLabsVideoConfigured(env: NodeJS.ProcessEnv = process.env): boolean {
  return elevenLabsVideoConfig(env).key !== null;
}

/** A generated video of `durationSec` covers a sentence that needs `neededSec`; a longer sentence takes the still. */
export function generatedVideoCoversSentence(neededSec: number, durationSec: number): boolean {
  return Number.isFinite(neededSec) && Number.isFinite(durationSec) && neededSec <= durationSec + 0.05;
}

/**
 * The same answer-about-the-account rule the still uses: 401/402/403 stand the service down for
 * 30 minutes; every other refusal stays per generation.
 */
const ACCOUNT_REFUSAL_STATUSES = new Set([401, 402, 403]);
export const VIDEO_ACCOUNT_REFUSAL_COOLDOWN_MS = 30 * 60_000;
let videoServiceRefusedUntil = 0;

export function videoServiceStandingDown(now = Date.now()): boolean {
  return now < videoServiceRefusedUntil;
}

export function resetVideoServiceStandDownForTests(): void {
  videoServiceRefusedUntil = 0;
}

function noteAccountRefusal(status: number): void {
  if (!ACCOUNT_REFUSAL_STATUSES.has(status)) return;
  videoServiceRefusedUntil = Math.max(videoServiceRefusedUntil, Date.now() + VIDEO_ACCOUNT_REFUSAL_COOLDOWN_MS);
  console.warn(
    formatProviderCooldown(GENERATED_VIDEO_PROVIDER, classifyProviderFailure({ status }), VIDEO_ACCOUNT_REFUSAL_COOLDOWN_MS)
  );
}

/** Writes an MP4 (video only) for the prompt to `outMp4`; true when the file is there. */
export type VideoClipGenerator = (
  prompt: string,
  outMp4: string,
  opts: { durationSec: number; deadlineAtMs: number }
) => Promise<boolean>;

let generatorOverride: VideoClipGenerator | null = null;
export function setVideoClipGeneratorForTests(g: VideoClipGenerator | null): void {
  generatorOverride = g;
}

let sleepImpl: (ms: number) => Promise<void> = (ms) => new Promise((r) => setTimeout(r, ms));
export function setVideoPollSleepForTests(s: ((ms: number) => Promise<void>) | null): void {
  sleepImpl = s ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
}

async function fetchWithAbort(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

type GenerationAnswer = {
  id?: string;
  generation_id?: string;
  status?: string;
  content_url?: string;
  content_mime_type?: string;
  failure_reason?: string;
  error?: unknown;
  [k: string]: unknown;
};

function generationId(j: GenerationAnswer): string | null {
  const id = typeof j.id === "string" ? j.id : typeof j.generation_id === "string" ? j.generation_id : null;
  return id && id.trim() ? id.trim() : null;
}

function failureText(j: GenerationAnswer): string {
  const raw = j.failure_reason ?? (typeof j.error === "string" ? j.error : (j.error as { message?: string } | undefined)?.message) ?? "";
  return String(raw).replace(/\s+/g, " ").slice(0, 160);
}

async function readGeneration(key: string, id: string): Promise<{ status: number; body: GenerationAnswer | null }> {
  const resp = await fetchWithAbort(
    `${API_BASE}/v1/flows/video/${encodeURIComponent(id)}`,
    { method: "GET", headers: { "xi-api-key": key, Accept: "application/json" } },
    POLL_TIMEOUT_MS
  );
  let body: GenerationAnswer | null = null;
  try {
    body = (await resp.json()) as GenerationAnswer;
  } catch {
    body = null;
  }
  return { status: resp.status, body };
}

/** The downloaded bytes, remuxed without audio: a generated soundtrack never reaches the film. */
async function writeVideoOnly(bytes: Buffer, outMp4: string): Promise<boolean> {
  const tmp = `${outMp4}.download.mp4`;
  fs.writeFileSync(tmp, bytes);
  try {
    await execFileAsync(resolveFFmpegBin(), ["-y", "-hide_banner", "-loglevel", "error", "-i", tmp, "-c:v", "copy", "-an", "-movflags", "+faststart", outMp4], {
      timeout: 60_000,
      maxBuffer: 1 << 20,
    });
    return fs.existsSync(outMp4) && fs.statSync(outMp4).size >= GENERATED_VIDEO_MIN_BYTES / 2;
  } catch (err) {
    console.warn(`[${GENERATED_VIDEO_FALLBACK}] the downloaded file could not be remuxed: ${(err as Error).message?.slice(0, 120)}`);
    return false;
  } finally {
    try { fs.unlinkSync(tmp); } catch { /* already gone */ }
  }
}

/**
 * The production generator: create, poll within the deadline, download, strip audio. Every exit
 * that is not a file on disk returns false and says why in one line — no key, standing down, a
 * refusal, no id, a failed generation, a time-out, a missing or expired content URL, a file too
 * small, a remux that failed.
 */
const elevenLabsGenerator: VideoClipGenerator = async (prompt, outMp4, opts) => {
  const cfg = elevenLabsVideoConfig();
  if (!cfg.key) return false;
  if (videoServiceStandingDown()) return false;
  const key = cfg.key;
  const startedAt = Date.now();
  let id: string | null = null;
  try {
    const body = {
      model_id: cfg.modelId,
      prompt: prompt.slice(0, 2000),
      duration_secs: opts.durationSec,
      aspect_ratio: "16:9",
      ...cfg.extra,
    };
    const created = await fetchWithAbort(
      `${API_BASE}/v1/flows/video`,
      { method: "POST", headers: { "xi-api-key": key, "Content-Type": "application/json", Accept: "application/json" }, body: JSON.stringify(body) },
      CREATE_TIMEOUT_MS
    );
    if (!created.ok) {
      console.warn(`[${GENERATED_VIDEO_FALLBACK}] the video service answered HTTP ${created.status} at create`);
      noteAccountRefusal(created.status);
      return false;
    }
    let answer: GenerationAnswer | null = null;
    try {
      answer = (await created.json()) as GenerationAnswer;
    } catch {
      answer = null;
    }
    id = answer ? generationId(answer) : null;
    if (!id) {
      console.warn(
        `[${GENERATED_VIDEO_FALLBACK}] the video service answered without a generation id (fields: ${answer ? Object.keys(answer).slice(0, 12).join(",") : "none"})`
      );
      return false;
    }
    console.log(
      `[${GENERATED_VIDEO_FALLBACK}] started id=${id} model=${cfg.modelId} duration=${opts.durationSec}s status=${answer?.status ?? "?"} keySource=${cfg.keySource ?? "none"} ` +
        `window=${Math.max(0, Math.round((opts.deadlineAtMs - Date.now()) / 1000))}s`
    );
  } catch (err) {
    console.warn(`[${GENERATED_VIDEO_FALLBACK}] the video service failed at create: ${(err as Error).message?.slice(0, 120)}`);
    return false;
  }

  let contentUrl: string | null = null;
  let pollErrors = 0;
  while (Date.now() < opts.deadlineAtMs) {
    const waitMs = Math.min(cfg.pollMs, Math.max(0, opts.deadlineAtMs - Date.now()));
    if (waitMs <= 0) break;
    await sleepImpl(waitMs);
    if (Date.now() >= opts.deadlineAtMs) break;
    let read: { status: number; body: GenerationAnswer | null };
    try {
      read = await readGeneration(key, id);
    } catch (err) {
      pollErrors++;
      console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} poll failed (${pollErrors}/${MAX_CONSECUTIVE_POLL_ERRORS}): ${(err as Error).message?.slice(0, 100)}`);
      if (pollErrors >= MAX_CONSECUTIVE_POLL_ERRORS) return false;
      continue;
    }
    if (read.status === 401 || read.status === 402 || read.status === 403) {
      console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} the video service answered HTTP ${read.status} at poll`);
      noteAccountRefusal(read.status);
      return false;
    }
    if (read.status === 404) {
      console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} unknown to the video service (HTTP 404)`);
      return false;
    }
    if (read.status < 200 || read.status >= 300 || !read.body) {
      pollErrors++;
      console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} poll answered HTTP ${read.status} (${pollErrors}/${MAX_CONSECUTIVE_POLL_ERRORS})`);
      if (pollErrors >= MAX_CONSECUTIVE_POLL_ERRORS) return false;
      continue;
    }
    pollErrors = 0;
    const status = String(read.body.status ?? "").toLowerCase();
    if (status === "completed") {
      contentUrl = typeof read.body.content_url === "string" && read.body.content_url ? read.body.content_url : null;
      if (!contentUrl) {
        console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} completed without content_url (fields: ${Object.keys(read.body).slice(0, 12).join(",")})`);
        return false;
      }
      console.log(`[${GENERATED_VIDEO_FALLBACK}] id=${id} completed in ${Math.round((Date.now() - startedAt) / 1000)}s mime=${read.body.content_mime_type ?? "?"}`);
      break;
    }
    if (status === "failed") {
      console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} failed after ${Math.round((Date.now() - startedAt) / 1000)}s — ${failureText(read.body) || "no reason given"} (not charged)`);
      return false;
    }
    /* pending / generating: keep waiting */
  }
  if (!contentUrl) {
    console.warn(
      `[${GENERATED_VIDEO_FALLBACK}] id=${id} not finished within ${Math.round((Date.now() - startedAt) / 1000)}s — left to the service; nothing placed`
    );
    return false;
  }

  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const dl = await fetchWithAbort(contentUrl, { method: "GET" }, DOWNLOAD_TIMEOUT_MS);
      if (!dl.ok) {
        console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} download answered HTTP ${dl.status}${attempt === 0 ? " — asking for a fresh link" : ""}`);
        if (attempt === 0) {
          const again = await readGeneration(key, id).catch(() => null);
          const fresh = again?.body && typeof again.body.content_url === "string" ? again.body.content_url : null;
          if (fresh) {
            contentUrl = fresh;
            continue;
          }
        }
        return false;
      }
      const bytes = Buffer.from(await dl.arrayBuffer());
      if (bytes.length < GENERATED_VIDEO_MIN_BYTES) {
        console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} download too small (${bytes.length} bytes)`);
        return false;
      }
      const ok = await writeVideoOnly(bytes, outMp4);
      if (ok) console.log(`[${GENERATED_VIDEO_FALLBACK}] id=${id} on disk (${bytes.length} bytes, audio removed) after ${Math.round((Date.now() - startedAt) / 1000)}s`);
      return ok;
    } catch (err) {
      console.warn(`[${GENERATED_VIDEO_FALLBACK}] id=${id} download failed: ${(err as Error).message?.slice(0, 120)}`);
      return false;
    }
  }
  return false;
};

export function videoClipGenerator(): VideoClipGenerator {
  return generatorOverride ?? elevenLabsGenerator;
}
